import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Boss } from '../Entity/Boss';
import type { Turret } from '../Entity/Turret';
import { Turret as TurretEntity } from '../Entity/Turret';
import { BATTLE_EVENT } from '../BattleEvents';

/**
 * 监听 TURRET_REBUILD_REQUEST，销毁旧炮台、按新阶段配置创建新炮台。
 * 阶段切换 = 全新阵容。
 */
export class SpawnSystem implements System {

    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        world.bus.on(BATTLE_EVENT.TURRET_REBUILD_REQUEST, this._onRebuild, this);
    }

    onDestroy(world: World): void {
        world.bus.off(BATTLE_EVENT.TURRET_REBUILD_REQUEST, this._onRebuild, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onRebuild(boss: Boss, stageIndex: number): void {
        // 1. 销毁旧炮台
        const oldIds = new Set(boss.turretIds);
        for (const t of this._world.query<Turret>('turret')) {
            if (oldIds.has(t.id)) {
                this._world.remove(t);
            }
        }
        boss.turretIds = [];

        // 2. 按新阶段配置创建
        const stage = boss.config.stages[stageIndex];
        if (!stage) return;

        for (const cfg of stage.turrets) {
            const turret = new TurretEntity();
            turret.ownerId = boss.id;
            turret.config = cfg;
            turret.hp = cfg.hp;
            turret.maxHp = cfg.hp;
            turret.collisionRadius = cfg.collisionRadius;
            turret.aimAngle = cfg.baseAngle;
            turret.x = boss.x + cfg.offsetX;
            turret.y = boss.y + cfg.offsetY;
            this._world.add(turret);
            boss.turretIds.push(turret.id);
        }
    }
}